# ------------------------------------------------------------------ SequentialGroupTest --
def test_sequential_single(scheduler):
    command = Command.no_requirements(co.yield_).named("The Command")
    sequence = SequentialGroup("The Sequence", [command])
    scheduler.schedule(sequence)
    scheduler.run()
    assert scheduler.is_running(sequence) and scheduler.is_running(command)
    scheduler.run()
    assert not scheduler.is_running(sequence) and not scheduler.is_running(command)


def test_sequential_two_commands(scheduler):
    c1 = Command.no_requirements(co.yield_).named("C1")
    c2 = Command.no_requirements(co.yield_).named("C2")
    sequence = SequentialGroup("C1 > C2", [c1, c2])
    scheduler.schedule(sequence)
    scheduler.run()
    assert scheduler.is_running(sequence)
    assert scheduler.is_running(c1)
    assert not scheduler.is_scheduled_or_running(c2)
    scheduler.run()
    assert scheduler.is_running(sequence)
    assert not scheduler.is_running(c1)
    assert scheduler.is_scheduled_or_running(c2)
    scheduler.run()
    assert not scheduler.is_running(sequence)
    assert not scheduler.is_running(c2)


