# -------------------------------------------------------------------- ParallelGroupTest --
def _counting(mech, n, count, name):
    def body():
        for _ in range(n):
            co.yield_()
            count.increment_and_get()

    return mech.run(body).named(name)


def test_parallel_all(scheduler):
    r1, r2 = DummyMechanism("R1", scheduler), DummyMechanism("R2", scheduler)
    n1, n2 = Ref(0), Ref(0)
    c1, c2 = _counting(r1, 5, n1, "C1"), _counting(r2, 10, n2, "C2")
    parallel = ParallelGroup("Parallel", [c1, c2], [])
    scheduler.schedule(parallel)
    scheduler.run()
    assert scheduler.is_running(parallel) and scheduler.is_running(c1) and scheduler.is_running(c2)
    for i in range(1, 5):
        scheduler.run()
        assert scheduler.is_running(c1) and scheduler.is_running(c2)
        assert n1.get() == i and n2.get() == i
    for i in range(5, 10):
        scheduler.run()
        assert not scheduler.is_running(c1) and scheduler.is_running(c2)
        assert n1.get() == 5 and n2.get() == i
    assert scheduler.is_running(parallel)
    scheduler.run()
    assert not scheduler.is_running(c1) and not scheduler.is_running(c2)
    assert not scheduler.is_running(parallel)
    assert n1.get() == 5 and n2.get() == 10


def test_race(scheduler):
    r1, r2 = DummyMechanism("R1", scheduler), DummyMechanism("R2", scheduler)
    n1, n2 = Ref(0), Ref(0)
    c1, c2 = _counting(r1, 5, n1, "C1"), _counting(r2, 10, n2, "C2")
    race = ParallelGroup("Race", [], [c1, c2])
    scheduler.schedule(race)
    scheduler.run()
    assert scheduler.is_running(race) and scheduler.is_running(c1) and scheduler.is_running(c2)
    for i in range(1, 5):
        scheduler.run()
        assert scheduler.is_running(c1) and scheduler.is_running(c2)
        assert n1.get() == i and n2.get() == i
    scheduler.run()
    assert not scheduler.is_running(race)
    assert not scheduler.is_running(c1) and not scheduler.is_running(c2)
    assert n1.get() == 5 and n2.get() == 5


def test_nested(scheduler):
    mechanism = DummyMechanism("mechanism", scheduler)
    count = Ref(0)
    command = _counting(mechanism, 5, count, "Command")
    inner = ParallelGroup("Inner", {command}, set())
    outer = ParallelGroup("Outer", set(), {inner})
    scheduler.schedule(outer)
    assert scheduler.is_scheduled(outer)
    assert not scheduler.is_scheduled_or_running(inner)
    assert not scheduler.is_scheduled_or_running(command)
    scheduler.run()
    assert scheduler.is_running(outer) and scheduler.is_running(inner) and scheduler.is_running(command)
    assert count.get() == 0
    for i in range(1, 5):
        scheduler.run()
        assert scheduler.is_running(outer) and scheduler.is_running(inner) and scheduler.is_running(command)
        assert count.get() == i
    scheduler.run()
    assert not scheduler.is_running(outer)
    assert not scheduler.is_running(inner)
    assert not scheduler.is_running(command)


